// The immutable base roster remains a stable historical source. Review waves
// replace only the *seed guide* used for future Worlds or missing-identity
// fallbacks: they cannot repack a wrestler who already has a saved persona.
const reviewedByName = new Map(
  [...REVIEWED_REAL_ROSTER_IDENTITIES_WAVE4, ...REVIEWED_REAL_ROSTER_IDENTITIES_WAVE5, ...REVIEWED_REAL_ROSTER_IDENTITIES_WAVE6, ...REVIEWED_REAL_ROSTER_IDENTITIES_WAVE7, ...REVIEWED_REAL_ROSTER_IDENTITIES_WAVE8, ...REVIEWED_REAL_ROSTER_IDENTITIES_WAVE9]
    .map(entry => [entry.name, entry]),
);
if (reviewedByName.size !==
    REVIEWED_REAL_ROSTER_IDENTITIES_WAVE4.length + REVIEWED_REAL_ROSTER_IDENTITIES_WAVE5.length + REVIEWED_REAL_ROSTER_IDENTITIES_WAVE6.length + REVIEWED_REAL_ROSTER_IDENTITIES_WAVE7.length + REVIEWED_REAL_ROSTER_IDENTITIES_WAVE8.length + REVIEWED_REAL_ROSTER_IDENTITIES_WAVE9.length)
  throw new Error("roster identity audits contain duplicate wrestler names");
export const FULL_REAL_ROSTER_IDENTITY_GUIDE: readonly FullRosterIdentityGuideEntry[] =
  BASE_FULL_REAL_ROSTER_IDENTITY_GUIDE.map(entry => {
    const reviewed = reviewedByName.get(entry.name);
    return reviewed ? { ...entry, ...structuredClone(reviewed), editorialBasis: "TARGETED" } : entry;
  });
if (FULL_REAL_ROSTER_IDENTITY_GUIDE.filter(entry => reviewedByName.has(entry.name)).length !== reviewedByName.size)
  throw new Error("roster identity audits contain a wrestler missing from real-roster seeds");
const identityByName = new Map<string,FullRosterIdentityGuideEntry>(
  FULL_REAL_ROSTER_IDENTITY_GUIDE.map(entry=>[entry.name.toLocaleLowerCase("en-GB"),entry])
);
if(identityByName.size!==FULL_REAL_ROSTER_IDENTITY_GUIDE.length)
  throw new Error("full real-roster identity guide contains duplicated names");
/** Returns isolated seed data so caller edits cannot mutate another World. */
export function fullRealRosterIdentityFor(name:string):FullRosterIdentityGuideEntry|null {
  const entry=identityByName.get(name.trim().toLocaleLowerCase("en-GB"));
  return entry?structuredClone(entry):null;
}
